// @vitest-environment jsdom
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount, type VueWrapper } from '@vue/test-utils'
import { createMemoryHistory, createRouter, type Router } from 'vue-router'

vi.mock('@/api/catalog', () => ({
  getLibraryPage: vi.fn(),
  getLibraryDetail: vi.fn(),
  getSharedApps: vi.fn(),
}))

import { getLibraryDetail, getLibraryPage, getSharedApps } from '@/api/catalog'
import CatalogView from './CatalogView.vue'

const USER_A = '11111111-1111-1111-1111-111111111111'
const USER_B = '22222222-2222-2222-2222-222222222222'

function emptyPage() {
  return { items: [], pageNum: 1, pageSize: 10, totalCount: 0 }
}

function deferred<T>() {
  let resolve!: (value: T) => void
  let reject!: (reason: unknown) => void
  const promise = new Promise<T>((res, rej) => {
    resolve = res
    reject = rej
  })
  return { promise, resolve, reject }
}

function buttonWithText(wrapper: VueWrapper, text: string) {
  const button = wrapper.findAll('[role="tab"]').find((item) => item.text() === text)
  if (!button) throw new Error(`탭을 찾지 못했습니다: ${text}`)
  return button
}

function createTestRouter(): Router {
  return createRouter({
    history: createMemoryHistory(),
    routes: [
      { path: '/catalog', name: 'catalog', component: CatalogView },
      { path: '/directory', name: 'directory', component: { template: '<div />' } },
    ],
  })
}

async function mountAt(location: string) {
  const router = createTestRouter()
  await router.push(location)
  await router.isReady()
  const wrapper = mount(CatalogView, { global: { plugins: [router] } })
  await flushPromises()
  return { router, wrapper }
}

beforeEach(() => {
  vi.mocked(getLibraryPage).mockReset().mockResolvedValue(emptyPage())
  vi.mocked(getSharedApps).mockReset().mockResolvedValue(emptyPage())
  vi.mocked(getLibraryDetail).mockReset()
})

describe('CatalogView 딥링크', () => {
  it('진입한 query의 사용자로 공유 앱을 조회한다', async () => {
    await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    expect(getSharedApps).toHaveBeenCalledTimes(1)
    expect(getSharedApps).toHaveBeenLastCalledWith(expect.objectContaining({ userId: USER_A, pageNum: 1 }))
    expect(getLibraryPage).not.toHaveBeenCalled()
  })

  // 사용자·부서 화면에서 다른 사용자의 공유 앱을 누르면 경로는 그대로고 query만 바뀐다.
  it('같은 경로의 query가 바뀌면 새 사용자로 다시 조회한다', async () => {
    const { router, wrapper } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    await router.push(`/catalog?tab=shared&userId=${USER_B}`)
    await flushPromises()

    expect(getSharedApps).toHaveBeenCalledTimes(2)
    expect(getSharedApps).toHaveBeenLastCalledWith(expect.objectContaining({ userId: USER_B, pageNum: 1 }))
    expect(wrapper.get<HTMLInputElement>('.shared-app-filter input[type="text"]').element.value).toBe(USER_B)
  })

  it('query에서 tab이 빠지면 자료실 목록으로 돌아간다', async () => {
    const { router, wrapper } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    await router.push('/catalog')
    await flushPromises()

    expect(getLibraryPage).toHaveBeenCalledTimes(1)
    expect(wrapper.find('.shared-app-filter').exists()).toBe(false)
  })

  it('화면이 쓰지 않는 query만 바뀌면 다시 조회하지 않는다', async () => {
    const { router } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    await router.push(`/catalog?tab=shared&userId=${USER_A}&highlight=1`)
    await flushPromises()

    expect(getSharedApps).toHaveBeenCalledTimes(1)
  })

  // 다른 화면으로 떠날 때도 route는 컴포넌트가 사라지기 전에 먼저 바뀐다.
  it('다른 경로로 이동하면 조회하지 않는다', async () => {
    const { router } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    await router.push('/directory')
    await flushPromises()

    expect(getSharedApps).toHaveBeenCalledTimes(1)
    expect(getLibraryPage).not.toHaveBeenCalled()
  })
})

describe('CatalogView 탭별 조회 상태', () => {
  // 탭을 옮긴 뒤에 도착한 실패는 떠나온 탭의 것이므로 지금 보는 탭에 표시해서는 안 된다.
  it('탭을 옮긴 뒤 도착한 공유 앱 실패가 자료실 탭에 남지 않는다', async () => {
    const failing = deferred<ReturnType<typeof emptyPage>>()
    vi.mocked(getSharedApps).mockReturnValueOnce(failing.promise)

    const { wrapper } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)

    await buttonWithText(wrapper, '자료실').trigger('click')
    failing.reject(new Error('공유 앱 조회 실패'))
    await flushPromises()

    expect(wrapper.text()).not.toContain('공유 앱 조회 실패')
  })

  // 두 탭이 loading 하나를 공유하면 공유 앱 조회가 진행 중일 때 자료실 목록이 skeleton으로 바뀐다.
  it('공유 앱 조회 중에도 자료실 탭은 목록을 유지한다', async () => {
    vi.mocked(getLibraryPage).mockResolvedValue({
      items: [{ id: 1, title: '운영 공지', groupCode: 'NOTICE', viewYn: 'Y', notifyYn: 'N', viewCnt: 3 }],
      pageNum: 1,
      pageSize: 10,
      totalCount: 1,
    })
    const pending = deferred<ReturnType<typeof emptyPage>>()
    vi.mocked(getSharedApps).mockReturnValueOnce(pending.promise)

    const { router, wrapper } = await mountAt('/catalog')
    expect(wrapper.text()).toContain('운영 공지')

    await router.push(`/catalog?tab=shared&userId=${USER_A}`)
    await flushPromises()
    expect(wrapper.find('.loading-block').exists()).toBe(true)

    await buttonWithText(wrapper, '자료실').trigger('click')
    await flushPromises()

    expect(wrapper.find('.loading-block').exists()).toBe(false)
    expect(wrapper.text()).toContain('운영 공지')
  })

  // "아직 조회하지 않았다"를 빈 배열로 판단하면 공유 앱이 0건인 사용자는 탭을 누를 때마다 같은 요청을 되풀이한다.
  it('0건으로 조회를 마친 탭은 다시 눌러도 재조회하지 않는다', async () => {
    const { wrapper } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)
    expect(wrapper.text()).toContain('최근 공유 앱이 없습니다.')

    await buttonWithText(wrapper, '자료실').trigger('click')
    await flushPromises()
    expect(wrapper.text()).toContain('조회된 자료실 콘텐츠가 없습니다.')

    await buttonWithText(wrapper, '사용자 공유 앱').trigger('click')
    await buttonWithText(wrapper, '자료실').trigger('click')
    await buttonWithText(wrapper, '사용자 공유 앱').trigger('click')
    await flushPromises()

    expect(getSharedApps).toHaveBeenCalledTimes(1)
    expect(getLibraryPage).toHaveBeenCalledTimes(1)
    wrapper.unmount()
  })

  // query의 userId가 바뀌면 이전 사용자의 공유 앱 결과는 무효다 — 조회 완료 플래그가 그 결과를 붙들고 있으면 안 된다.
  it('query의 사용자가 바뀌면 조회를 마친 공유 앱 탭도 다시 읽는다', async () => {
    const { router, wrapper } = await mountAt(`/catalog?tab=shared&userId=${USER_A}`)
    expect(getSharedApps).toHaveBeenCalledTimes(1)

    await router.push(`/catalog?userId=${USER_B}`)
    await flushPromises()
    expect(getLibraryPage).toHaveBeenCalledTimes(1)

    await buttonWithText(wrapper, '사용자 공유 앱').trigger('click')
    await flushPromises()

    expect(getSharedApps).toHaveBeenCalledTimes(2)
    expect(getSharedApps).toHaveBeenLastCalledWith(expect.objectContaining({ userId: USER_B }))
    wrapper.unmount()
  })
})
export interface RequestTicket {
  isLatest(): boolean
}

export interface RequestGuard {
  start(): RequestTicket
  invalidate(): void
}

// 목록·상세 조회는 페이지 이동, 탭 전환, 행 선택으로 동시에 여러 번 시작될 수 있다.
// 늦게 도착한 이전 응답이 최신 결과를 덮어쓰지 않도록 요청 순서를 추적한다.
export function createRequestGuard(): RequestGuard {
  let issued = 0
  return {
    start() {
      const ticket = ++issued
      return { isLatest: () => ticket === issued }
    },
    // 요청을 시작하지 않고 진행 중인 응답만 버릴 때 사용한다.
    invalidate() {
      issued += 1
    },
  }
}

