    const pending = deferred()
    vi.mocked(apiGet).mockReturnValueOnce(pending.promise).mockResolvedValueOnce(B)
    const { wrapper } = await mountView()
    await select(wrapper)
    await select(wrapper, 1)
    if (outcome === '성공') pending.resolve(A)
    else pending.reject(new Error('이전 요청 오류'))
    await flushPromises()
    expectDetail(wrapper, B, A)
    expect(wrapper.text()).not.toContain('이전 요청 오류')
  })

  for (const action of ['새로고침', '검색', 'query', '닫기'] as const) {
    for (const outcome of ['성공', '실패'] as const) {
      it("'`${action}은 상세 결과·오류를 초기화하고 무효화된 ${outcome} 응답이 패널을 열지 않는다`, async () => {
        const pending = deferred()
        vi.mocked(apiGet).mockRejectedValueOnce(new Error('"'상세 서버 오류')).mockResolvedValueOnce(A).mockReturnValueOnce(pending.promise)
        const { wrapper, router } = await mountView()
        let queryIndex = 0
        async function reset() {
          if (action === '새로고침') await wrapper.findAll('button').find(button => button.text().includes('새로고침'))"'!.trigger('"'click')
          else if (action === '검색') await wrapper.get('.catalog-filter').trigger('submit')
          else if (action === 'query') await router.push("'`/catalog?userId=user-${++queryIndex}&tab=shared`)
          else await wrapper.get('"'[aria-label=\"상세 닫기\"]').trigger('click')
          await flushPromises()
          expect(wrapper.find('.detail-sheet').exists()).toBe(false)
        }
        async function returnToLibrary() {
          if (action === 'query') {
            await wrapper.get('[role=\"tab\"]').trigger('click')
            await flushPromises()
          }
        }
        await select(wrapper)
        expectFailure(wrapper)
        await reset()
        await returnToLibrary()
        await select(wrapper)
        expectDetail(wrapper, A, B)
        await reset()
        await returnToLibrary()
        await select(wrapper, 1)
        await reset()
        if (outcome === '성공') pending.resolve(B)
        else pending.reject(new Error('무효화된 오류'))
        await flushPromises()
        expect(wrapper.find('.detail-sheet').exists()).toBe(false)
        expect(wrapper.text()).not.toContain('무효화된 오류')
        expect(apiGet).toHaveBeenCalledTimes(3)
      })
    }
  }
})
EOF"

